#include <gtk/gtk.h>
#include <gdk/gdk.h>
#include <gio/gio.h>
#include <stdlib.h>

void on_tree_view_row_activated(GtkTreeView *tree_view, GtkTreePath *tree_path_UNUSED, GtkTreeViewColumn *column, gpointer user_data) {
    GtkTreeModel *model = NULL;
    GtkTreeIter iter;
    gchar *item_name = NULL;
    gboolean has_multiple_lines = FALSE;

    if (!gtk_tree_model_get_iter_first(GTK_TREE_MODEL(model), &iter)) {
        g_free(item_name);
        return;
    }

    gtk_tree_model_get(model, &iter,
                         0, &item_name,
                         1, &has_multiple_lines,
                         -1);

    if (!item_name || !has_multiple_lines) {
        g_free(item_name);
        return;
    }

    gchar *file_path = g_build_filename(g_get_user_config_dir(), "problem_texts", item_name, NULL);
    GError *error = NULL;

    if (g_file_test(file_path, G_FILE_TEST_EXISTS)) {
        GAppInfo *app_info = g_app_info_get_default_for_type("text/plain", FALSE);
        GFile *file = g_file_new_for_path(file_path);

        if (app_info && g_app_info_launch_default_for_uri("file://" file_path, NULL, &error)) {
            g_object_unref(app_info);
            g_object_unref(file);
        } else {
            GtkWidget *dialog;
            GtkWidget *text_view;
            GtkTextBuffer *buffer;
            gchar *file_contents = NULL;
            gsize length = 0;

            if (g_file_get_contents(file_path, &file_contents, &length, NULL)) {
                dialog = gtk_dialog_new_with_buttons("Edit Text", GTK_WINDOW(gtk_window_get_toplevel(GTK_WIDGET(tree_view))),
                                                     GTK_DIALOG_MODAL | GTK_DIALOG_DESTROY_WITH_PARENT,
                                                     "_Save", GTK_RESPONSE_ACCEPT,
                                                     "_Cancel", GTK_RESPONSE_CANCEL,
                                                     NULL);

                text_view = gtk_text_view_new();
                gtk_text_view_set_editable(GTK_TEXT_VIEW(text_view), TRUE);
                buffer = gtk_text_buffer_new(NULL);
                gtk_text_buffer_set_text(buffer, file_contents, length);
                g_free(file_contents);
                gtk_container_add(GTK_CONTAINER(gtk_dialog_get_content_area(GTK_DIALOG(dialog))), text_view);

                gtk_widget_show_all(dialog);

                if (gtk_dialog_run(GTK_DIALOG(dialog)) == GTK_RESPONSE_ACCEPT) {
                    GtkTextIter start, end;
                    gchar *new_text;

                    gtk_text_buffer_get_bounds(buffer, &start, &end);
                    new_text = gtk_text_buffer_get_text(buffer, &start, &end, FALSE);

                    g_file_set_contents(file_path, new_text, -1, NULL);
                    g_free(new_text);

                    // Update problem data and GUI state here
                }

                gtk_widget_destroy(dialog);
            } else {
                // Handle case where file could not be read
            }

            g_clear_error(&error);
            g_free(file_path);
        }
    } else {
        g_free(file_path);
    }

    g_free(item_name);
}

#include <gtk/gtk.h>
#include <stdlib.h>
#include <gio/gdesktopappinfo.h>
#include <glib.h>

void on_tree_view_row_activated(GtkTreeView* tree_view, GtkTreePath* tree_path_UNUSED, GtkTreeViewColumn* column, gpointer user_data) {
    GtkTreeSelection* selection = gtk_tree_view_get_selection(tree_view);
    GtkTreeModel* model;
    GtkTreeIter iter;

    if (gtk_tree_selection_get_selected(selection, &model, &iter)) {
        gchar* item_name = NULL;

        gtk_tree_model_get(model, &iter, 0, &item_name, -1);
        if (item_name && g_strrstr(item_name, "\n")) {
            gchar* file_path = g_build_filename(g_get_user_config_dir(), "data", item_name, NULL);
            GError* error = NULL;
            gboolean success = g_app_info_launch_default_for_uri(file_path, NULL, &error);

            if (!success) {
                GtkWidget* dialog = gtk_dialog_new_with_buttons("Edit Text", GTK_WINDOW(gtk_window_get_toplevel(GTK_WIDGET(tree_view))), GTK_DIALOG_MODAL,
                    GTK_STOCK_SAVE, GTK_RESPONSE_ACCEPT, GTK_STOCK_CANCEL, GTK_RESPONSE_REJECT, NULL);

                GtkWidget* text_view = gtk_text_view_new();
                GtkTextBuffer* buffer = gtk_text_buffer_new(NULL);
                gtk_text_buffer_set_text(buffer, item_name, -1);
                gtk_text_view_set_buffer(GTK_TEXT_VIEW(text_view), buffer);

                GtkWidget* content_area = gtk_dialog_get_content_area(GTK_DIALOG(dialog));
                gtk_box_pack_start(GTK_BOX(content_area), text_view, TRUE, TRUE, 0);
                gtk_widget_show_all(dialog);

                gint response = gtk_dialog_run(GTK_DIALOG(dialog));
                if (response == GTK_RESPONSE_ACCEPT) {
                    GtkTextIter start_iter, end_iter;
                    gchar* new_text = NULL;

                    gtk_text_buffer_get_bounds(buffer, &start_iter, &end_iter);
                    new_text = gtk_text_buffer_get_text(buffer, &start_iter, &end_iter, FALSE);

                    g_free(item_name);
                    item_name = new_text;

                    // Update the GUI and problem data here (custom logic based on application)
                }

                gtk_widget_destroy(dialog);
            }

            g_free(file_path);
        }

        g_free(item_name);
    }
}

