#include <gtk/gtk.h>
#include <glib.h>
#include <stdlib.h>

void on_tree_view_row_activated(GtkTreeView *tree_view, GtkTreePath *tree_path_UNUSED, GtkTreeViewColumn *column, gpointer user_data) {
    GtkTreeIter iter;
    GtkTreeModel *model = gtk_tree_view_get_model(tree_view);
    gchar *item_name = NULL;
    gchar *file_path = NULL;

    if (gtk_tree_model_get_iter(model, &iter, tree_path_UNUSED)) {
        gtk_tree_model_get(model, &iter, 0, &item_name, -1);
    }

    if (item_name && g_strv_length(g_strsplit(item_name, "\n", -1)) > 1) {
        gboolean success = system(g_strdup_printf("xdg-open %s > /dev/null 2>&1", item_name)) == 0;

        if (!success) {
            GtkWidget *dialog = gtk_dialog_new_with_buttons("Edit Text", GTK_WINDOW(gtk_window_get_toplevel(GTK_WIDGET(tree_view))),
                                                            GTK_DIALOG_MODAL, GTK_STOCK_CANCEL, GTK_RESPONSE_CANCEL, GTK_STOCK_OK, GTK_RESPONSE_OK, NULL);
            GtkWidget *text_view = gtk_text_view_new();
            GtkTextBuffer *buffer = gtk_text_buffer_new(NULL);
            GtkTextIter start, end;

            gtk_container_add(GTK_CONTAINER(gtk_dialog_get_content_area(GTK_DIALOG(dialog))), text_view);
            gtk_text_buffer_set_text(buffer, item_name, -1);
            gtk_text_view_set_buffer(GTK_TEXT_VIEW(text_view), buffer);

            gint result = gtk_dialog_run(GTK_DIALOG(dialog));
            if (result == GTK_RESPONSE_OK) {
                gtk_text_buffer_get_bounds(buffer, &start, &end);
                gchar *new_text = gtk_text_buffer_get_text(buffer, &start, &end, FALSE);
                g_free(item_name);
                item_name = new_text;
                file_path = item_name; // assuming the item_name is the file path
                g_file_set_contents(file_path, item_name, -1, NULL);
            }

            gtk_widget_destroy(dialog);
        }

        g_free(item_name);
    }
}
